// FUNCTION: BFME2 0x0050DBE6 size=380 name=?populateBeacon@ControlBar@@QAEXPAVObject@@@Z evidence=N:ledger tier=B hypothesis:name:Z
void ControlBar::populateBeacon(Object *beacon)
{
	// set the portrait for the thing being constructed
	setPortraitByObject(beacon);

	static NameKeyType textID = TheNameKeyGenerator->nameToKey("ControlBar.wnd:EditBeaconText");
	static NameKeyType staticTextID = TheNameKeyGenerator->nameToKey("ControlBar.wnd:StaticTextBeaconLabel");
	static NameKeyType clearButtonID = TheNameKeyGenerator->nameToKey("ControlBar.wnd:ButtonClearBeaconText");

	GameWindow *textEntryWin = TheWindowManager->winGetWindowFromId(0, textID);
	GameWindow *staticTextWin = TheWindowManager->winGetWindowFromId(0, staticTextID);
	GameWindow *buttonWin = TheWindowManager->winGetWindowFromId(0, clearButtonID);

	if (beacon->isLocallyControlled())
	{
		if (textEntryWin)
		{
			textEntryWin->winHide(false);
			GadgetTextEntrySetText(textEntryWin, beacon->getDrawable()->getCaptionText());
			TheWindowManager->winSetFocus(textEntryWin);
		}

		if (staticTextWin)
			staticTextWin->winHide(false);

		if (buttonWin)
			buttonWin->winHide(false);
	}
	else
	{
		if (textEntryWin)
			textEntryWin->winHide(true);

		if (staticTextWin)
			staticTextWin->winHide(true);

		if (buttonWin)
			buttonWin->winHide(true);
	}
}
